// generated by gen_matrix. wire-dispatch variant: carrier_disp_ifchainasc_real runs the interpret_ifchain_ascending
// interpreter over a program from the "real" profile. Only the dispatch fn
// differs across a bench's variants; the program crosses FFI as bytes and every
// interpreter fills `results`, then the caller folds one checksum (the current
// fidelity-gate call shape).
use mockspace_bench_core::{timed, FfiBenchCall};
use mockspace_bench_macro::bench_variant;
use std::sync::OnceLock;
use vehje_bench_carrier::{checksum, generate, ir, GenParams, interpret_ifchain_ascending};

static BYTES: OnceLock<Vec<u8>> = OnceLock::new();
const ITERS: usize = 16;

#[bench_variant("carrier_disp_ifchainasc_real", sizes = [64, 256, 1024, 4096, 16384])]
fn run<const N: usize>(input: &[u8; N], output: &mut [u8; 8]) -> FfiBenchCall {
    let bytes = BYTES.get_or_init(|| {
        let mut gp = GenParams::profile("real").unwrap();
        gp.node_count = N;
        ir::encode(&generate(&gp), &ir::REC24)
    });
    let d = ir::Decoded::parse(bytes, ir::REC24).unwrap();
    let mut results = vec![0u64; d.node_count];
    timed! { run {
        let mut acc: u64 = 0;
        let mut k = 0usize;
        while k < ITERS {
            interpret_ifchain_ascending(&d, input[k % N] as u64 ^ (k as u64), &mut results);
            acc ^= checksum(&results);
            k += 1;
        }
        output.copy_from_slice(&acc.to_le_bytes());
    } }
}
